const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Shared by the initial server response and client-side product navigation.
export function productLoading(product,sku=''){
 const variants=product?.variants||[],variant=variants.find(v=>v.sku===sku&&v.images?.[0])||variants.find(v=>!v.discontinued&&v.images?.[0]),image=variant?.images?.[0];
 return `<section class="wrap section pf-product-loading" aria-busy="true"><a class="text-link" href="/produkter">← Tilbage til produkter</a><div class="pf-design-heading"><div><p class="eyebrow">${escape(product?.brand)}</p><h1>${escape(product?.name||'Produkt')}</h1></div></div><div class="pf-design-layout"><div>${image?`<img class="pf-loading-photo" src="${escape(image)}" alt="${escape(product.name)} i farven ${escape(variant.color||'vist variant')}" width="500" height="500" fetchpriority="high">`:''}</div><div class="pf-loading-options"><p class="small muted" role="status">Henter valgmuligheder…</p><div class="pf-loading-field" aria-hidden="true"></div><div class="pf-loading-field" aria-hidden="true"></div><div class="pf-loading-field" aria-hidden="true"></div></div></div></section>`;
}
